function draw() {
  // clear
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  // planet
  ctx.fillStyle = '#555';
  ctx.beginPath();
  ctx.arc(planet.x, planet.y, planet.r, 0, Math.PI * 2);
  ctx.fill();
  // ship
  const sx = planet.x + Math.cos(ship.angle) * ship.radius;
  const sy = planet.y + Math.sin(ship.angle) * ship.radius;
  ctx.fillStyle = '#0f0';
  ctx.beginPath();
  ctx.arc(sx, sy, ship.r, 0, Math.PI * 2);
  ctx.fill();
  // asteroids
  ctx.fillStyle = '#a33';
  for (const a of asteroids) {
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
    ctx.fill();
  }
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#fff';
    ctx.font = '24px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
  }
}

input.newString:
function draw() {
  // clear background
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  // stars background
  ctx.fillStyle = 'white';
  for (const s of stars) {
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.size, 0, Math.PI * 2);
    ctx.fill();
  }
  // planet with radial gradient
  const grad = ctx.createRadialGradient(planet.x, planet.y, planet.r * 0.2, planet.x, planet.y, planet.r);
  grad.addColorStop(0, '#777');
  grad.addColorStop(1, '#222');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(planet.x, planet.y, planet.r, 0, Math.PI * 2);
  ctx.fill();
  // ship as triangle
  const sx = planet.x + Math.cos(ship.angle) * ship.radius;
  const sy = planet.y + Math.sin(ship.angle) * ship.radius;
  const shipAngle = Math.atan2(sy - planet.y, sx - planet.x);
  ctx.fillStyle = '#0f0';
  ctx.beginPath();
  ctx.moveTo(
    sx + Math.cos(shipAngle) * ship.r * 2,
    sy + Math.sin(shipAngle) * ship.r * 2
  );
  ctx.lineTo(
    sx + Math.cos(shipAngle + Math.PI * 0.8) * ship.r,
    sy + Math.sin(shipAngle + Math.PI * 0.8) * ship.r
  );
  ctx.lineTo(
    sx + Math.cos(shipAngle - Math.PI * 0.8) * ship.r,
    sy + Math.sin(shipAngle - Math.PI * 0.8) * ship.r
  );
  ctx.closePath();
  ctx.fill();
  // asteroids with gray stroke
  ctx.strokeStyle = '#aaa';
  ctx.lineWidth = 2;
  for (const a of asteroids) {
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
    ctx.stroke();
  }
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#fff';
    ctx.font = '24px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
  }
}

